import { useMockData } from '../common';
import { accessRestricted, trustedOperationRequired } from '../../lib/security/secureContracts';

export interface AuditLogEntry {
  id?: string;
  userId?: string;
  userEmail?: string;
  action: string;
  entity: string;
  entityId?: string;
  metadata?: Record<string, unknown>;
  createdAt?: string;
}

/**
 * Mock-only compatibility helper. Live audit attribution must be generated by
 * an internal trusted database/function boundary, never from browser fields.
 */
export async function logAction(entry: AuditLogEntry): Promise<AuditLogEntry> {
  if (useMockData) {
    return { ...entry, id: `audit-${Date.now()}`, createdAt: new Date().toISOString() };
  }
  throw trustedOperationRequired('trusted audit event persistence');
}

/** Raw audit history is intentionally unavailable until an approved activity projection exists. */
export async function fetchAuditLogs(): Promise<AuditLogEntry[]> {
  if (useMockData) return [];
  throw accessRestricted('raw audit history');
}
